class Solution{func getMaxGridHappiness(_ m:Int,_ n:Int,_ introvertsCount:Int,_ extrovertsCount:Int)->Int{let I=introvertsCount,E=extrovertsCount;var rows=m,cols=n;if cols>rows{swap(&rows,&cols)};var k=1;for _ in 0..<cols{k*=3};var h=Array(repeating:0,count:k),a=h,b=h;for x in 0..<k{var q=x,p=0;for _ in 0..<cols{let d=q%3;q/=3;if d==1{h[x]+=120;a[x]+=1}else if d==2{h[x]+=40;b[x]+=1};if d>0&&p>0{h[x]+=(d==1 ? -30:20)+(p==1 ? -30:20)};p=d}};var M=[String:Int]();func f(_ r:Int,_ i:Int,_ e:Int,_ p:Int)->Int{if r==rows{return 0};let z="\(r),\(i),\(e),\(p)";if let v=M[z]{return v};var v=0;for c in 0..<k where a[c]<=i&&b[c]<=e{var x=p,y=c,s=0;for _ in 0..<cols{let u=x%3,d=y%3;x/=3;y/=3;if u>0&&d>0{s+=(u==1 ? -30:20)+(d==1 ? -30:20)}};v=max(v,h[c]+s+f(r+1,i-a[c],e-b[c],c))};M[z]=v;return v};return f(0,I,E,0)}}
